<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{request}from'../../api/client';const items=ref<any[]>([]),orders=ref<any[]>([]);const published=computed(()=>items.value.filter(x=>x.status===1).length),paid=computed(()=>items.value.filter(x=>x.is_paid).length),pending=computed(()=>orders.value.filter(x=>x.status==='PENDING').length);async function load(){try{items.value=(await request('/api/v1/admin/dramas?page=1&page_size=100')).items||[]}catch{items.value=[{id:101,title:'The Contract Wife',country:'US',language:'en',status:1,is_paid:true},{id:102,title:'Revenge of the Hidden Heiress',country:'US',language:'en',status:1,is_paid:true}]}try{orders.value=(await request('/api/v1/admin/orders?page=1&page_size=100')).items||[]}catch{orders.value=[]}}onMounted(load)</script>
<template><section><div class="title"><p>OVERVIEW</p><h1>数据概览</h1><span>海外短剧运营核心指标</span></div><div class="stats"><el-card><small>短剧总数</small><strong>{{items.length}}</strong></el-card><el-card><small>已发布</small><strong>{{published}}</strong></el-card><el-card><small>付费剧</small><strong>{{paid}}</strong></el-card><el-card><small>待支付订单</small><strong>{{pending}}</strong></el-card></div><el-card class="panel"><template #header>最近短剧</template><el-table :data="items.slice(0,8)"><el-table-column prop="id" label="ID"/><el-table-column prop="title" label="标题"/><el-table-column prop="country" label="国家"/><el-table-column prop="language" label="语言"/><el-table-column prop="status" label="状态"/></el-table></el-card></section></template>